text:
Hi everyone, 
 I’m sharing a SAP RAP topic: Actions , Factory Function and Functions . 
 Factory Actions are a special type of action, 
 I kept this explanation small and simple on purpose. If we put all RAP topics into one app, it becomes hard to understand. Learning one topic at a time gives better clarity on how it works.Every business app needs more than create, update and delete. Users want to click Start , Approve or Close . They also want to ask questions like “how many days are left?” 
 In SAP RAP (ABAP RESTful Application Programming Model), you build both with actions and functions . 

 The memory trick 
 Changes data → Action 
 Only reads → Function 
 Makes a new copy: factory action 

 If it saves something, it’s an action. If it only answers a question, it’s a function. 

 Our example: a Task app 
 The app has tasks with a status: New → In Progress → Completed. We build one action ( Start ) and one function ( Days Left ). 

 Step 1: Create the database table 
 @EndUserText.label : 'Task'
@AbapCatalog.enhancement.category : #NOT_EXTENSIBLE
@AbapCatalog.tableCategory : #TRANSPARENT
@AbapCatalog.deliveryClass : #A
@AbapCatalog.dataMaintenance : #RESTRICTED
define table ztask {
 key client : abap.clnt not null;
 key task_id : sysuuid_x16 not null;
 title : abap.char(60);
 description : abap.char(255);
 status : abap.char(1);
 priority : abap.char(1);
 due_date : abap.dats;
 created_by : abp_creation_user;
 created_at : abp_creation_tstmpl;
 last_changed_by : abp_lastchange_user;
 last_changed_at : abp_lastchange_tstmpl;
 local_last_changed_at : abp_locinst_lastchange_tstmpl;

} 
 Step 2: Create the Root Interface View @AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: '. Interface view (Root View)'
@Metadata.ignorePropagatedAnnotations: true
define root view entity ZI_Task
 as select from ztask
{
 key task_id as TaskId,
 title as Title,
 description as Description,
 status as Status,

 cast( case status
 when 'N' then 'New'
 when 'P' then 'In Progress'
 when 'C' then 'Completed'
 when 'X' then 'Cancelled'
 else 'Unknown'
 end as abap.char(12) ) as StatusText,

 case status
 when 'C' then 3
 when 'P' then 2
 when 'X' then 1
 else 0
end as StatusCriticality,

 priority as Priority,
 due_date as DueDate,

 @Semantics.user.createdBy: true
 created_by as CreatedBy,
 @Semantics.systemDateTime.createdAt: true
 created_at as CreatedAt,
 @Semantics.user.lastChangedBy: true
 last_changed_by as LastChangedBy,
 @Semantics.systemDateTime.lastChangedAt: true
 last_changed_at as LastChangedAt,
 @Semantics.systemDateTime.localInstanceLastChangedAt: true
 local_last_changed_at as LocalLastChangedAt
} 
 Step 3: Create the two abstract entities @EndUserText.label: 'Priority Input'
define abstract entity ZA_TaskPriority
{
 @EndUserText.label: 'Priority (L, M or H)'
 Priority : abap.char(1);
}

@EndUserText.label: 'Days Left Result'
define abstract entity ZA_TaskDays
{
 DaysLeft : abap.int4;
} 
 Step 4: Create the Behavior Definition 
 managed implementation in class zbp_i_task unique;
strict ( 2 );
with draft;

define behavior for ZI_Task alias Task
persistent table ztask
draft table ztask_d
lock master total etag LastChangedAt
authorization master ( global )
etag master LocalLastChangedAt
{
 create;
 update;
 delete;

 draft action Edit;
 draft action Activate;
 draft action Discard;
 draft action Resume;
 draft determine action Prepare
 {
 validation validateTitle;
 }

 validation validateTitle on save { create; update; field Title; }

 field ( numbering : managed, readonly ) TaskId;
 field ( readonly ) Status, StatusText, StatusCriticality,
 CreatedBy, CreatedAt, LastChangedBy,
 LastChangedAt, LocalLastChangedAt;
 field ( mandatory ) Title;

 determination setInitialStatus on modify { create; }

 // ACTION: changes data. Shows as a button.
 // Example: user selects a New task and clicks Start -> status becomes In Progress.
 // features : instance = button is enabled or disabled per task.
 // result [1] $self = returns the updated task so the screen refreshes.
 action ( features : instance ) startTask result [1] $self;

 // ACTION: changes data.
 // Example: click Complete on an In Progress task -> status becomes Completed.
 action ( features : instance ) completeTask result [1] $self;

 // ACTION: changes data.
 // Example: click Cancel on a New or In Progress task -> status becomes Cancelled.
 action ( features : instance ) cancelTask result [1] $self;

 // ACTION WITH PARAMETER: opens a popup to ask the user for input.
 // Example: click Set Priority, popup asks for L, M or H, then the priority is saved.
 // parameter ZA_TaskPriority = the input structure shown in the popup.
 action ( features : instance ) setPriority parameter ZA_TaskPriority result [1] $self;

 // FACTORY ACTION: creates a NEW record from an existing one.
 // Example: select "Fix login bug", click Copy -> new task "Fix login bug (Copy)" is created.
 factory action ( features : instance ) copyTask [1];

 // FUNCTION: only reads and returns a value. Changes nothing. No button.
 // Example: call getDaysLeft on a task due in 2 days -> returns { "DaysLeft": 2 }.
 // result [1] ZA_TaskDays = the structure that holds the answer.
 function getDaysLeft result [1] ZA_TaskDays;

 mapping for ztask
 {
 TaskId = task_id;
 Title = title;
 Description = description;
 Status = status;
 Priority = priority;
 DueDate = due_date;
 CreatedBy = created_by;
 CreatedAt = created_at;
 LastChangedBy = last_changed_by;
 LastChangedAt = last_changed_at;
 LocalLastChangedAt = local_last_changed_at;
 }
} 
