 Step 6: Create the behavior class CLASS lhc_task DEFINITION INHERITING FROM cl_abap_behavior_handler.
 PRIVATE SECTION.
 METHODS startTask FOR MODIFY IMPORTING keys FOR ACTION Task~startTask RESULT result.
 METHODS completeTask FOR MODIFY IMPORTING keys FOR ACTION Task~completeTask RESULT result.
 METHODS cancelTask FOR MODIFY IMPORTING keys FOR ACTION Task~cancelTask RESULT result.
 METHODS setPriority FOR MODIFY IMPORTING keys FOR ACTION Task~setPriority RESULT result.
 METHODS copyTask FOR MODIFY IMPORTING keys FOR ACTION Task~copyTask.

 METHODS getDaysLeft FOR READ IMPORTING keys FOR FUNCTION Task~getDaysLeft RESULT result.
ENDCLASS.

CLASS lhc_task IMPLEMENTATION.

 " ACTION: Start (status = In Progress)
 METHOD startTask.
 MODIFY ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task UPDATE FIELDS ( Status )
 WITH VALUE #( FOR key IN keys ( %tky = key-%tky Status = 'P' ) )
 FAILED failed
 REPORTED reported.

 READ ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task ALL FIELDS
 WITH CORRESPONDING #( keys )
 RESULT DATA(lt_tasks).

 result = VALUE #( FOR ls_task IN lt_tasks
 ( %tky = ls_task-%tky %param = ls_task ) ).
 ENDMETHOD.

 " ACTION: Complete (status = Completed)
 METHOD completeTask.
 MODIFY ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task UPDATE FIELDS ( Status )
 WITH VALUE #( FOR key IN keys ( %tky = key-%tky Status = 'C' ) )
 FAILED failed
 REPORTED reported.

 READ ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task ALL FIELDS
 WITH CORRESPONDING #( keys )
 RESULT DATA(lt_tasks).

 result = VALUE #( FOR ls_task IN lt_tasks
 ( %tky = ls_task-%tky %param = ls_task ) ).
 ENDMETHOD.

 " ACTION: Cancel (status = Cancelled)
 METHOD cancelTask.
 MODIFY ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task UPDATE FIELDS ( Status )
 WITH VALUE #( FOR key IN keys ( %tky = key-%tky Status = 'X' ) )
 FAILED failed
 REPORTED reported.

 READ ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task ALL FIELDS
 WITH CORRESPONDING #( keys )
 RESULT DATA(lt_tasks).

 result = VALUE #( FOR ls_task IN lt_tasks
 ( %tky = ls_task-%tky %param = ls_task ) ).
 ENDMETHOD.

 " ACTION WITH PARAMETER: Set Priority (popup input L, M or H)
 METHOD setPriority.
 DATA lt_valid TYPE TABLE FOR UPDATE zi_task\\Task.

 LOOP AT keys INTO DATA(key).
 IF key-%param-Priority = 'L' OR key-%param-Priority = 'M' OR key-%param-Priority = 'H'.
 APPEND VALUE #( %tky = key-%tky Priority = key-%param-Priority ) TO lt_valid.
 ELSE.
 APPEND VALUE #( %tky = key-%tky ) TO failed-task.
 APPEND VALUE #( %tky = key-%tky
 %msg = new_message_with_text(
 severity = if_abap_behv_message=>severity-error
 text = 'Priority must be L, M or H' )
 %action-setPriority = if_abap_behv=>mk-on ) TO reported-task.
 ENDIF.
 ENDLOOP.

 IF lt_valid IS NOT INITIAL.
 MODIFY ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task UPDATE FIELDS ( Priority )
 WITH lt_valid.
 ENDIF.

 READ ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task ALL FIELDS
 WITH CORRESPONDING #( keys )
 RESULT DATA(lt_tasks).

 result = VALUE #( FOR ls_task IN lt_tasks
 ( %tky = ls_task-%tky %param = ls_task ) ).
 ENDMETHOD.

 " FACTORY ACTION: Copy Task (creates a new task)
 METHOD copyTask.
 DATA lt_create TYPE TABLE FOR CREATE zi_task\\Task.

 READ ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task
 FIELDS ( Title Description Priority DueDate )
 WITH CORRESPONDING #( keys )
 RESULT DATA(lt_tasks).

 LOOP AT lt_tasks INTO DATA(ls_task).
 APPEND VALUE #( %cid = keys[ KEY entity %key = ls_task-%key ]-%cid
 Title = |{ ls_task-Title } (Copy)|
 Description = ls_task-Description
 Priority = ls_task-Priority
 DueDate = ls_task-DueDate ) TO lt_create.
 ENDLOOP.

 MODIFY ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task
 CREATE FIELDS ( Title Description Priority DueDate )
 WITH lt_create
 MAPPED DATA(lt_mapped).

 mapped-task = lt_mapped-task.
 ENDMETHOD.

 " FUNCTION: Days Left (only reads, changes nothing)
 METHOD getDaysLeft.
 READ ENTITIES OF zi_task IN LOCAL MODE
 ENTITY Task FIELDS ( DueDate )
 WITH CORRESPONDING #( keys )
 RESULT DATA(lt_tasks).

 DATA(lv_today) = cl_abap_context_info=>get_system_date( ).

 result = VALUE #( FOR ls_task IN lt_tasks
 ( %tky = ls_task-%tky
 %param-DaysLeft = COND #( WHEN ls_task-DueDate IS INITIAL
 THEN 0
 ELSE ls_task-DueDate - lv_today ) ) ).
 ENDMETHOD.

ENDCLASS. 
